window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[189]={"id":"189","numero":189,"titre":"Déficits immunitaires de l'enfant et de l'adulte","objectifs":[{"id":"189-1","rang":"A","rubrique":"Définition","titre":"Connaître la différence entre déficits immunitaires acquis et héréditaires","contenu":"<p>Un <span class=\"kw-def\">déficit immunitaire</span> est un défaut <strong>quantitatif ou fonctionnel</strong> portant sur <span class=\"kw-chiffre\">≥ 1</span> composant du système immunitaire. Il expose à un risque de pathologies <span class=\"kw-alerte\">infectieuses</span>, <span class=\"kw-alerte\">tumorales</span>, <span class=\"kw-alerte\">granulomateuses</span> et <span class=\"kw-alerte\">auto-immunes</span> selon le type de déficit.</p>\n      <p>Trois compartiments peuvent être touchés :</p>\n      <ul>\n        <li><span class=\"kw-def\">Immunité innée</span> — <span class=\"kw-bio\">polynucléaires</span>, cellules NK, <span class=\"kw-bio\">monocytes</span>/macrophages, cellules dendritiques, système du <span class=\"kw-bio\">complément</span>, cytokines</li>\n        <li><span class=\"kw-def\">Immunité adaptative humorale</span> = <strong>LB</strong> — <span class=\"kw-chiffre\">IgM</span>, IgG, IgA, IgE</li>\n        <li><span class=\"kw-def\">Immunité adaptative cellulaire</span> = <strong>LT</strong> — <span class=\"kw-chiffre\">CD4</span> helper, CD8 cytotoxiques</li>\n      </ul>\n      <p>La distinction <strong><span class=\"kw-etio\">héréditaire</span> / acquis</strong> structure toute la démarche :</p>\n      <table >\n        <thead><tr><th></th><th>Déficits héréditaires / primitifs (DIH)</th><th>Déficits secondaires / <span class=\"kw-etio\">acquis</span></th></tr></thead>\n        <tbody>\n          <tr>\n            <th>Âge</th>\n            <td>Plus fréquents chez l'<span class=\"kw-clinique\">enfant</span> ; révélation possible chez l'adulte, surtout pour <span class=\"kw-clinique\">les</span> déficits humoraux</td>\n            <td>Plus fréquents chez l'<span class=\"kw-clinique\">adulte</span> — plus l'âge est élevé, plus la probabilité d'un déficit <span class=\"kw-etio\">acquis</span> est forte</td>\n          </tr>\n          <tr>\n            <th>Causes</th>\n            <td>DIH <span class=\"kw-clinique\">les</span> plus fréquents : <span class=\"kw-etio\">déficit isolé en IgA</span> ; <span class=\"kw-etio\">DICV</span></td>\n            <td><strong>Pathologiques :</strong> <span class=\"kw-etio\">dénutrition</span> ; <span class=\"kw-etio\">insuffisance rénale</span> ; <span class=\"kw-etio\">diabète</span> ; <span class=\"kw-etio\">cirrhose</span><br><strong>Physiologiques :</strong> <span class=\"kw-etio\">grossesse</span> ; <span class=\"kw-etio\">vieillissement</span><br><strong>Intoxications :</strong> <span class=\"kw-etio\">alcoolisme</span> ; <span class=\"kw-etio\">tabagisme</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 169 — <span class=\"kw-etio\">VIH</span></em></p>","frequence":0},{"id":"189-2","rang":"B","rubrique":"Epidémiologie","titre":"Savoir qu’un déficit immunitaire primitif (DIP) peut se révéler à l’âge adulte","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">déficits immunitaires primitifs (DIP)</span> sont des pathologies génétiques <strong>rares</strong> : fréquence estimée à <span class=\"kw-chiffre\">1/4 000 naissances</span>, avec plus de <span class=\"kw-chiffre\">430 DIH</span> décrits à ce jour avec une cause moléculaire identifiée.</p>\n      <p>La <strong>majorité</strong> se révèle dans l'<span class=\"kw-clinique\">enfance</span> (infections, <span class=\"kw-etio\">auto-immunité</span>, auto-inflammation, néoplasies, parfois <span class=\"kw-ci\">allergie</span>). <strong>Mais certains se révèlent plus tardivement</strong>, à l'adolescence voire à l'âge adulte — en particulier le <span class=\"kw-def\">DICV</span> :</p>\n      <ul>\n        <li>Diagnostic le plus souvent posé chez l'<span class=\"kw-clinique\">adolescent ou l'adulte jeune</span> (<span class=\"kw-chiffre\">20-40 ans</span>)</li>\n        <li><span class=\"kw-clinique\">Les</span> premiers symptômes remontent néanmoins souvent à l'enfance</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>À retenir.</strong> Un déficit immunitaire primitif n'est <strong>pas qu'une maladie pédiatrique</strong> : devant un adulte qui enchaîne <span class=\"kw-clinique\">les</span> infections récurrentes, il faut savoir évoquer un DIP non encore diagnostiqué, surtout un <span class=\"kw-def\">déficit humoral</span>.\n      </div>","frequence":0},{"id":"189-3","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir quand évoquer le diagnostic de déficit immunitaire chez l’enfant et l’adulte","contenu":"<p>Le diagnostic de déficit immunitaire doit être évoqué devant des <span class=\"kw-clinique\">infections répétées, sévères ou inhabituelles</span>. <span class=\"kw-clinique\">Les</span> seuils diffèrent entre l'enfant et l'adulte :</p>\n      <table >\n        <thead><tr><th>Signe d'appel</th><th>Enfant</th><th>Adulte</th></tr></thead>\n        <tbody>\n          <tr><th>ATCD familial</th><td>Antécédent familial de déficit immunitaire</td><td>Antécédent familial de déficit immunitaire</td></tr>\n          <tr><th>Otite moyenne aiguë</th><td><span class=\"kw-chiffre\">≥ 8/an</span> avant <span class=\"kw-chiffre\">4 ans</span> ; <span class=\"kw-chiffre\">≥ 4/an</span> après <span class=\"kw-chiffre\">4 ans</span></td><td><span class=\"kw-chiffre\">≥ 2/an</span></td></tr>\n          <tr><th>Sinusite</th><td><span class=\"kw-chiffre\">≥ 2/an</span></td><td><span class=\"kw-chiffre\">≥ 2/an</span></td></tr>\n          <tr><th>Pneumopathie</th><td><span class=\"kw-chiffre\">≥ 2/an</span></td><td><span class=\"kw-chiffre\">≥ 2/an</span></td></tr>\n          <tr><th>Infections sévères ou inhabituelles</th>\n            <td>Infection sévère/invasive à <span class=\"kw-bio\">bactérie encapsulée</span> (<span class=\"kw-def\">sepsis</span>, <span class=\"kw-def\">méningite</span>) ; infections récurrentes à <span class=\"kw-bio\">pyogènes</span> (<span class=\"kw-clinique\">folliculite</span>, <span class=\"kw-clinique\">abcès</span>, <span class=\"kw-clinique\">cellulite</span>) ; <span class=\"kw-clinique\">diarrhée infectieuse persistante</span> ; <span class=\"kw-clinique\">muguet ou candidose récidivante</span> ; infection mycobactérienne ganglionnaire ou osseuse</td>\n            <td>Infection <span class=\"kw-etio\">bactérienne</span> invasive à <span class=\"kw-bio\">germe encapsulé</span> ; <span class=\"kw-clinique\">mycose cutanéomuqueuse persistante</span></td>\n          </tr>\n          <tr><th>Autres signes</th>\n            <td><span class=\"kw-alerte\">Cassure staturo-pondérale</span> ; retard de chute du cordon <span class=\"kw-chiffre\">&gt; 21 j</span> (chute normale vers J10) ; <span class=\"kw-clinique\">eczéma</span> sévère ou atypique ; <span class=\"kw-etio\">auto-immunité</span> (AHAI, PTI hors âge habituel) ; lymphoproliférations, <span class=\"kw-clinique\">adénopathies</span>, <span class=\"kw-clinique\">hépatosplénomégalie</span></td>\n            <td><span class=\"kw-clinique\">Diarrhée</span> chronique avec <span class=\"kw-clinique\">amaigrissement</span> ; maladies auto-immunes ou granulomateuses ; épisodes de <span class=\"kw-clinique\">fièvre inexpliquée</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p>Chez l'enfant, l'ensemble de ces manifestations peut aboutir à une <span class=\"kw-alerte\">anomalie de croissance staturo-pondérale</span>.</p>\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> <span class=\"kw-clinique\">Les</span> infections <span class=\"kw-clinique\">virales respiratoires banales</span> (rhinopharyngite, laryngite, trachéite, bronchite, bronchiolite) <strong>sans <span class=\"kw-alerte\">signe de gravité</span> ni surinfection <span class=\"kw-etio\">bactérienne</span></strong> n'évoquent <strong>pas</strong> un déficit immunitaire — elles orientent plutôt vers une <span class=\"kw-etio\">hyperréactivité bronchique</span> ou des <span class=\"kw-etio\">anomalies morphologiques ORL</span>.\n      </div>\n      <p>Le type d'infection oriente d'emblée vers un compartiment immunitaire :</p>\n      <table >\n        <thead><tr><th>Infections / pathogènes</th><th>Type de déficit</th><th>Bilans utiles</th></tr></thead>\n        <tbody>\n          <tr><td>Bactéries <span class=\"kw-bio\">encapsulées</span> (<span class=\"kw-etio\">pneumocoque</span>, Hib, <span class=\"kw-ttt\">méningocoque</span>)</td>\n            <td>Immunité <strong>humorale</strong> (<span class=\"kw-def\">LB</span>)</td>\n            <td>Dosage pondéral des Ig ; <span class=\"kw-bio\">sérologies</span> post-vaccinales et post-infectieuses ; sous-classes d'<span class=\"kw-chiffre\">IgG</span></td></tr>\n          <tr><td>Mycobactéries ; virus du groupe Herpès sévères (<span class=\"kw-etio\">VZV</span>, CMV) ; infections <span class=\"kw-bio\">opportunistes</span> (toxoplasmose, pneumocystose, cryptosporidiose)</td>\n            <td>Immunité <strong>cellulaire</strong> (<span class=\"kw-def\">LT</span>)</td>\n            <td><span class=\"kw-bio\">NFS</span> (<span class=\"kw-bio\">lymphopénie</span> ?) ; phénotypage lymphocytaire T/B/NK ; proliférations lymphocytaires T</td></tr>\n          <tr><td>Bactéries <span class=\"kw-bio\">pyogènes</span> ; infections fongiques (<span class=\"kw-bio\">Aspergillus</span>)</td>\n            <td>Déficit <strong>phagocytaire / inné</strong></td>\n            <td><span class=\"kw-bio\">NFS</span> (<span class=\"kw-bio\">neutropénie</span> ?) ; étude fonctionnelle des phagocytes ; recherche d'un défaut d'adhésion leucocytaire ; dosage des <span class=\"kw-chiffre\">IgE</span></td></tr>\n          <tr><td>Infections bactériennes invasives ; bactéries encapsulées ; <span class=\"kw-alerte\">paludisme grave</span></td>\n            <td>Déficit du <strong><span class=\"kw-bio\">complément</span></strong> ou <span class=\"kw-etio\">asplénie</span></td>\n            <td><span class=\"kw-bio\">NFS</span> ; <span class=\"kw-bio\">frottis sanguin</span> (<span class=\"kw-bio\">corps de Jolly</span> ?) ; exploration des voies classique et alterne du <span class=\"kw-bio\">complément</span> (C3, C4, CH50, AP50)</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 147 — <span class=\"kw-clinique\">Fièvre</span> aiguë · 151 — <span class=\"kw-def\">Méningite</span> - <span class=\"kw-clinique\">méningoencéphalite</span> · 158 — <span class=\"kw-def\">Sepsis</span> et <span class=\"kw-def\">choc septique</span></em></p>","frequence":3},{"id":"189-4","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les signes d’appel évocateur d’un déficit immunitaire commun variable","contenu":"<p>Le <span class=\"kw-def\">déficit immunitaire commun variable (DICV)</span> est un groupe hétérogène d'affections, défini par <strong>3 critères</strong> :</p>\n      <ul>\n        <li>Présence de <span class=\"kw-bio\">LB circulants</span></li>\n        <li><span class=\"kw-bio\">Hypogammaglobulinémie</span> portant sur <span class=\"kw-clinique\">les</span> <strong><span class=\"kw-chiffre\">IgG</span></strong> (± <span class=\"kw-chiffre\">IgA</span> et/ou IgM)</li>\n        <li>Production <strong>faible ou absente d'anticorps spécifiques</strong> après immunisation vaccinale ou après infection</li>\n      </ul>\n      <p><strong><span class=\"kw-def\">Terrain</span> :</strong> diagnostic chez l'<span class=\"kw-clinique\">adolescent ou l'adulte jeune</span> (<span class=\"kw-chiffre\">20-40 ans</span>), avec des premiers symptômes remontant souvent à l'enfance ; <span class=\"kw-chiffre\">cas intra-familiaux dans 20 %</span> ; <span class=\"kw-def\">prévalence</span> <span class=\"kw-chiffre\">1/25 000 – 1/30 000</span>.</p>\n      <table >\n        <thead><tr><th>Manifestation</th><th>Fréquence</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Infections répétées</span></td><td><span class=\"kw-chiffre\">100 %</span></td>\n            <td>Germes <span class=\"kw-bio\">encapsulés</span> ++ ; localisations <strong>ORL</strong> (otites, sinusites, rhinopharyngites) et <strong>pulmonaires</strong> (bronchites, pneumopathies) ; une <span class=\"kw-alerte\">toux chronique doit faire évoquer une dilatation des bronches</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Syndrome lymphoprolifératif</span></td><td><span class=\"kw-chiffre\">40 %</span></td>\n            <td><span class=\"kw-clinique\">Adénopathies</span> généralisées ; <span class=\"kw-clinique\">splénomégalie</span> ; hépatomégalie ; anomalies de l'<span class=\"kw-bio\">hémogramme</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Diarrhée chronique</span></td><td><span class=\"kw-chiffre\">20-50 %</span></td>\n            <td>Atrophie villositaire ; parasites (<span class=\"kw-bio\">Giardia</span>) ; bactéries (<span class=\"kw-etio\">Campylobacter</span>, Salmonella) ; hyperplasie nodulaire lymphoïde</td></tr>\n          <tr><td><span class=\"kw-clinique\">Auto-immunité</span></td><td><span class=\"kw-chiffre\">25 %</span></td>\n            <td>Cytopénies auto-immunes (anémie, thrombopénie, neutropénie) ; maladie de Biermer ; connectivite ; <span class=\"kw-def\">thyroïdite</span> <span class=\"kw-etio\">auto-immune</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Granulomatose</span></td><td><span class=\"kw-chiffre\">10-20 %</span></td>\n            <td>Complique le diagnostic en orientant à tort vers une <span class=\"kw-clinique\">sarcoïdose</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> La granulomatose du DICV peut faire évoquer à tort une <span class=\"kw-etio\">sarcoïdose</span>. Discriminant clé : la <span class=\"kw-clinique\">sarcoïdose</span> s'accompagne d'une <strong>hyper</strong><span class=\"kw-bio\">gammaglobulinémie</span>, le DICV d'une <strong>hypo</strong><span class=\"kw-bio\">gammaglobulinémie</span>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 211 — <span class=\"kw-clinique\">Sarcoïdose</span> · 194 — <span class=\"kw-def\">Lupus</span> - SAPL</em></p>","frequence":3},{"id":"189-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les complications des traitements immunosuppresseurs","contenu":"<p><span class=\"kw-clinique\">Les</span> traitements <span class=\"kw-ttt\">immunosuppresseurs</span> induisent un <span class=\"kw-def\">déficit immunitaire secondaire</span> dont la principale complication est <strong>infectieuse</strong> — le profil de germes dépend du mécanisme :</p>\n      <table >\n        <thead><tr><th>Traitement</th><th>Mécanisme</th><th>Risque <span class=\"kw-etio\">infectieux</span></th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-ttt\">AINS</span></td><td>Altération de l'immunité innée</td><td>Infections à <span class=\"kw-bio\">pyogènes</span> ; majoration du risque de complication grave</td></tr>\n          <tr><td><span class=\"kw-ttt\">Corticothérapie</span></td><td>Altération de l'immunité innée, <strong>dose-dépendante</strong></td><td>Infections à <span class=\"kw-bio\">pyogènes</span> <strong>et</strong> infections <span class=\"kw-bio\">opportunistes</span></td></tr>\n          <tr><td><span class=\"kw-ttt\">Immunosuppresseurs</span> (surtout post-greffe)</td><td>Neutropénie / lymphopénie</td><td>Infections à <span class=\"kw-bio\">pyogènes</span> et <span class=\"kw-bio\">opportunistes</span></td></tr>\n          <tr><td><span class=\"kw-ttt\">Biothérapies</span></td><td>Variable selon la molécule</td><td><span class=\"kw-bio\">Pyogènes</span>, <span class=\"kw-bio\">opportunistes</span> ou <span class=\"kw-bio\">encapsulées</span></td></tr>\n          <tr><td><span class=\"kw-ttt\">Chimiothérapie cytotoxique</span></td><td>Neutropénie / lymphopénie</td><td>Infections favorisées par la cytopénie</td></tr>\n          <tr><td><span class=\"kw-ttt\">Anti-épileptiques</span> / anti-comitiaux</td><td>Défaut de production d'Ig</td><td><span class=\"kw-bio\">Hypogammaglobulinémie</span></td></tr>\n        </tbody>\n      </table>\n      <p>La prévention de ces complications repose sur une <strong>prophylaxie anti-infectieuse</strong> ciblée :</p>\n      <table >\n        <thead><tr><th>Molécule</th><th>Prévient</th><th>Chez qui</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-ttt\">Cotrimoxazole</span></td><td>Toxoplasmose ; <span class=\"kw-alerte\">pneumocystose</span></td><td>Greffés ; <span class=\"kw-ttt\">corticothérapie</span> prolongée ; <span class=\"kw-etio\">VIH</span> avec <span class=\"kw-chiffre\">CD4</span> <span class=\"kw-chiffre\">&lt; 200/mm³</span></td></tr>\n          <tr><td><span class=\"kw-ttt\">Aciclovir / Valaciclovir</span></td><td>Infections à <span class=\"kw-bio\">CMV</span></td><td>Greffe de CSH ; greffé d'organe solide si donneur positif</td></tr>\n          <tr><td><span class=\"kw-ttt\">Ivermectine</span></td><td><span class=\"kw-alerte\">Anguillulose maligne</span></td><td>Patients sous <span class=\"kw-ttt\">corticoïdes</span> ayant séjourné en pays tropical (même si le séjour est ancien)</td></tr>\n          <tr><td><span class=\"kw-ttt\">Fluconazole</span></td><td>Candidoses systémiques</td><td>Pendant <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3 mois</span> post-allogreffe de CSH</td></tr>\n          <tr><td><span class=\"kw-ttt\">Pénicilline V</span></td><td><span class=\"kw-etio\">Pneumocoque</span></td><td>Patient asplénique</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 169 — <span class=\"kw-etio\">VIH</span> · 191 — <span class=\"kw-clinique\">Fièvre</span> chez l'immunodéprimé</em></p>","frequence":0},{"id":"189-6","rang":"B","rubrique":"Contenu multimédia","titre":"Electrophorèse des protides sériques : hypogammaglobulinémie","contenu":"<p>L'<span class=\"kw-bio\">électrophorèse des protéines sériques (EPP)</span> est l'examen de <strong>1ʳᵉ intention</strong> pour explorer la production d'anticorps chez l'<span class=\"kw-clinique\">adolescent et l'adulte</span> — réalisée <strong>avant</strong> le dosage pondéral des Ig, car le taux est <span class=\"kw-bio\">stable</span> à cet âge. Elle apprécie la production <strong>globale et polyclonale</strong> d'immunoglobulines.</p>\n      <p><strong>Sémiologie de l'hypogammaglobulinémie :</strong> diminution de la <span class=\"kw-bio\">fraction gamma-globulines</span> du tracé. Une fraction gamma <span class=\"kw-alerte\">effondrée</span> traduit un déficit de production d'Ig polyclonales.</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/189/epp-hypogammaglobulinemie.png\" alt=\"Tracé d'électrophorèse des protéines sériques montrant une hypogammaglobulinémie : fraction gamma-globulines diminuée\" loading=\"lazy\">\n        <figcaption>Électrophorèse des protides sériques — hypogammaglobulinémie : effondrement de la fraction gamma-globulines. Source : à compléter (fiche source EDN item 189).</figcaption>\n      </figure>\n      <!-- TODO Kevin : déposer <span class=\"kw-bio\"><span class=\"kw-bio\">epp</span></span>-hypogammaglobulinemie.png dans assets/images/189/ -->\n      <div class=\"callout callout-warn\">\n        <strong>Discriminant clé.</strong> Trois aspects de la fraction gamma à distinguer :\n        <ul>\n          <li><strong>Hypogammaglobulinémie</strong> — fraction gamma <span class=\"kw-bio\">diminuée, aplatie</span></li>\n          <li><strong>Pic monoclonal</strong> — pic <span class=\"kw-alerte\">étroit et pointu</span> (myélome, LLC)</li>\n          <li><strong>Hypergammaglobulinémie polyclonale</strong> — fraction gamma <span class=\"kw-bio\">élargie</span> (<span class=\"kw-clinique\">sarcoïdose</span>, hépatopathie)</li>\n        </ul>\n      </div>\n      <p>Devant une hypogammaglobulinémie, l'<span class=\"kw-bio\">immunofixation des protéines sériques</span> complète l'<span class=\"kw-bio\">EPP</span> pour rechercher ou éliminer un composant monoclonal.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 320 — Myélome multiple des os · 318 — Leucémie lymphoïde chronique</em></p>","frequence":3},{"id":"189-7","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les examens paracliniques de première intention pour explorer une hypogammaglobulinémie","contenu":"<p>Devant une <span class=\"kw-bio\">hypogammaglobulinémie</span>, le bilan de <strong>1ʳᵉ intention</strong> cherche avant tout une <span class=\"kw-etio\">cause secondaire</span> :</p>\n      <ul>\n        <li><span class=\"kw-bio\">NFS</span></li>\n        <li><span class=\"kw-bio\">Bandelette urinaire</span> + <span class=\"kw-bio\">rapport protéinurie/créatininurie</span> sur échantillon (ou <span class=\"kw-bio\">protéinurie</span> des <span class=\"kw-chiffre\">24 h</span>) — recherche de pertes rénales ou digestives, surtout si <span class=\"kw-bio\">hypoalbuminémie &lt; 30 g/L</span></li>\n        <li><span class=\"kw-bio\">Immunofixation des protéines sériques</span></li>\n        <li><span class=\"kw-bio\">Dosage des chaînes légères libres sériques</span> — recherche d'un myélome à chaînes légères en l'absence de pic</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> <span class=\"kw-alerte\">Pas de myélogramme à ce stade</span> — le myélogramme n'est pas un examen de 1ʳᵉ intention de l'exploration d'une hypogammaglobulinémie.\n      </div>\n      <p><span class=\"kw-clinique\">Les</span> <strong>causes secondaires</strong> à éliminer :</p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Causes</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-ttt\">Médicaments</span></td><td><span class=\"kw-ttt\">Corticoïdes</span> ; immunosuppresseurs ; <span class=\"kw-ttt\">rituximab</span> ; anti-épileptiques</td></tr>\n          <tr><td>Défaut de production</td><td>Lymphoprolifération maligne : <span class=\"kw-etio\">myélome</span>, <span class=\"kw-etio\">LLC</span>, maladie de Hodgkin</td></tr>\n          <tr><td>Pertes</td><td><span class=\"kw-etio\">Syndrome néphrotique</span> ; entéropathie exsudative ; dermatoses étendues</td></tr>\n        </tbody>\n      </table>\n      <p>En <strong>2ᵉ intention</strong> : <span class=\"kw-imagerie\">TDM</span> thoraco-abdomino-pelvienne, dosage pondéral des <span class=\"kw-chiffre\">IgG</span>/IgA/IgM, immunophénotypage lymphocytaire. Si le bilan reste négatif (hypogammaglobulinémie profonde, symptomatique, sans cause secondaire) → le diagnostic retenu est le <span class=\"kw-def\">DICV</span>, diagnostic d'élimination.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 320 — Myélome multiple des os · 318 — Leucémie lymphoïde chronique</em></p>","frequence":2},{"id":"189-8","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge d’un déficit immunitaire commun variable","contenu":"<p>La prise en charge du <span class=\"kw-def\">DICV</span> repose sur 4 axes :</p>\n      <table >\n        <thead><tr><th>Axe</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Traitement substitutif</strong></td>\n            <td><span class=\"kw-ttt\">Immunoglobulines polyvalentes</span> (voie <strong>IV ou sous-cutanée</strong>) — indiquées en cas d'infections à répétition avec <span class=\"kw-alerte\">retentissement pulmonaire</span></td></tr>\n          <tr><td><strong>Complications infectieuses</strong></td>\n            <td><span class=\"kw-ttt\">Antibiothérapie</span> systématique en cas d'infection : <strong>précoce et prolongée</strong>, ciblant <span class=\"kw-clinique\">les</span> germes <span class=\"kw-bio\">encapsulés</span></td></tr>\n          <tr><td><strong>Vaccinations</strong></td>\n            <td>Vaccins inertes : efficacité diminuée mais non nulle → vaccinations <span class=\"kw-ttt\">anti-grippale</span> et <span class=\"kw-ttt\">anti-pneumococcique</span> toujours recommandées</td></tr>\n          <tr><td><strong>Dilatation des bronches</strong></td>\n            <td><span class=\"kw-clinique\">Kinésithérapie respiratoire</span> indiquée en cas de DDB</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>À retenir.</strong> <span class=\"kw-clinique\">Les</span> <span class=\"kw-ci\">vaccins vivants atténués</span> sont <strong><span class=\"kw-ci\">contre-indiqués</span></strong> dans le DICV.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 146 — <span class=\"kw-ttt\">Vaccination</span></em></p>","frequence":0}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"liensGlobaux":[{"href":"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/hematologie-cancerologie/deficits-immunitaires-hereditaires#:~:text=Les%20d%C3%A9ficits%20immunitaires%20h%C3%A9r%C3%A9ditaires%20","label":"Pedia-univ — Deficits immunitaires hereditaires"}],"cards":[{"i":"211ca4d55306","n":189,"o":"189-1","u":"Définition","t":"Connaître la différence entre déficits immunitaires acquis et héréditaires","q":"Quelles sont les principales causes des déficits immunitaires acquis (secondaires) chez l'adulte, selon le cours ?","a":"<p>Les principales causes des déficits immunitaires acquis sont :</p><ul><li>Des <strong>états pathologiques</strong> : dénutrition, insuffisance rénale, diabète, cirrhose.</li><li>Des <strong>situations physiologiques</strong> : grossesse, vieillissement.</li><li>Des <strong>intoxications</strong> : alcoolisme, tabagisme.</li></ul>"},{"i":"383ae854a559","n":189,"o":"189-1","u":"Définition","t":"Connaître la différence entre déficits immunitaires acquis et héréditaires","q":"Comment distingue-t-on les déficits immunitaires héréditaires (primitifs) des déficits immunitaires acquis (secondaires) ?","a":"<p>La distinction se fait principalement sur l'<strong>étiologie</strong> et l'<strong>âge de révélation</strong> :</p><ul><li>Les déficits immunitaires <strong>héréditaires (primitifs)</strong> sont d'origine génétique et prédominent chez l'<strong>enfant</strong>, bien qu'une révélation soit possible à l'âge adulte (notamment pour les déficits humoraux).</li><li>Les déficits immunitaires <strong>acquis (secondaires)</strong> sont causés par des facteurs externes ou d'autres pathologies sous-jacentes. Ils sont plus fréquents chez l'<strong>adulte</strong> et leur probabilité augmente avec l'âge.</li></ul>"},{"i":"83c0c4471c54","n":189,"o":"189-1","u":"Définition","t":"Connaître la différence entre déficits immunitaires acquis et héréditaires","q":"Quelle est la définition générale d'un déficit immunitaire (DI) ?","a":"<p>Un déficit immunitaire est un <strong>défaut quantitatif ou fonctionnel</strong> portant sur au moins un composant du système immunitaire. Il expose le patient à un risque accru de pathologies <strong>infectieuses</strong>, <strong>tumorales</strong>, <strong>granulomateuses</strong> et <strong>auto-immunes</strong>.</p>"},{"i":"17cc2178ea40","n":189,"o":"189-3","u":"Diagnostic positif","t":"Savoir quand évoquer le diagnostic de déficit immunitaire chez l’enfant et l’adulte","q":"Quel type d'infections et quels signes orientent vers un déficit de l'immunité cellulaire (lymphocytes T) et quels examens sont pertinents ?","a":"<p>Les infections orientant vers un déficit de l'immunité cellulaire sont :</p><ul><li>Les <strong>mycobactéries</strong>.</li><li>Les <strong>virus du groupe Herpès sévères</strong> (ex : <strong>VZV</strong>, <strong>CMV</strong>).</li><li>Les <strong>infections opportunistes</strong> (ex : <strong>toxoplasmose</strong>, <strong>pneumocystose</strong>, <strong>cryptosporidiose</strong>).</li></ul><p>Les examens pertinents sont :</p><ul><li>Une <strong>Numération Formule Sanguine (NFS)</strong> à la recherche d'une <strong>lymphopénie</strong>.</li><li>Un <strong>phénotypage lymphocytaire T/B/NK</strong>.</li><li>Des <strong>proliférations lymphocytaires T</strong>.</li></ul>"},{"i":"4d3c1750841d","n":189,"o":"189-3","u":"Diagnostic positif","t":"Savoir quand évoquer le diagnostic de déficit immunitaire chez l’enfant et l’adulte","q":"Dans quelle situation n'évoque-t-on PAS un déficit immunitaire chez l'enfant, malgré des infections répétées ?","a":"<p>Malgré des infections répétées, les <strong>infections virales respiratoires banales</strong> (comme la rhinopharyngite, la laryngite, la trachéite, la bronchite ou la bronchiolite) <strong>sans signe de gravité ni surinfection bactérienne</strong> n'évoquent généralement pas un déficit immunitaire. Elles orientent plutôt vers une hyperréactivité bronchique ou des anomalies morphologiques ORL.</p>"},{"i":"64bc32e6d79b","n":189,"o":"189-3","u":"Diagnostic positif","t":"Savoir quand évoquer le diagnostic de déficit immunitaire chez l’enfant et l’adulte","q":"Quels types d'infections suggèrent un déficit phagocytaire ou de l'immunité innée, et quels bilans faut-il réaliser ?","a":"<p>Un déficit phagocytaire ou de l'immunité innée est suggéré par :</p><ul><li>Des <strong>infections à bactéries pyogènes</strong>.</li><li>Des <strong>infections fongiques</strong> (notamment <strong>Aspergillus</strong>).</li></ul><p>Les bilans à réaliser incluent :</p><ul><li>Une <strong>Numération Formule Sanguine (NFS)</strong> à la recherche d'une <strong>neutropénie</strong>.</li><li>Une <strong>étude fonctionnelle des phagocytes</strong>.</li><li>La recherche d'un <strong>défaut d'adhésion leucocytaire</strong>.</li><li>Le <strong>dosage des IgE</strong>.</li></ul>"},{"i":"8cf4db84bd73","n":189,"o":"189-3","u":"Diagnostic positif","t":"Savoir quand évoquer le diagnostic de déficit immunitaire chez l’enfant et l’adulte","q":"Quels sont les signes cliniques non infectieux qui doivent faire évoquer un déficit immunitaire chez l'enfant ?","a":"<p>Chez l'enfant, les signes cliniques non infectieux évocateurs d'un déficit immunitaire sont :</p><ul><li>Une <strong>cassure staturo-pondérale</strong>.</li><li>Un <strong>retard de chute du cordon > 21 jours</strong> (par rapport à la chute normale vers J10).</li><li>Un <strong>eczéma sévère ou atypique</strong>.</li><li>Une <strong>auto-immunité</strong> (ex : anémie hémolytique auto-immune ou purpura thrombopénique immunologique en dehors de l'âge habituel).</li><li>Des <strong>lymphoproliférations</strong>, <strong>adénopathies</strong>, ou une <strong>hépatosplénomégalie</strong>.</li></ul>"},{"i":"985b149e0aa6","n":189,"o":"189-3","u":"Diagnostic positif","t":"Savoir quand évoquer le diagnostic de déficit immunitaire chez l’enfant et l’adulte","q":"Quand doit-on évoquer un diagnostic de déficit immunitaire (DI) chez un enfant en termes de fréquence des infections ORL ?","a":"<p>On doit évoquer un déficit immunitaire chez un enfant en cas de :</p><ul><li><strong>Otites moyennes aiguës (OMA)</strong> : <strong>≥ 8 par an</strong> avant 4 ans, ou <strong>≥ 4 par an</strong> après 4 ans.</li><li><strong>Sinusites</strong> : <strong>≥ 2 par an</strong>.</li></ul>"},{"i":"ed5e94410c00","n":189,"o":"189-3","u":"Diagnostic positif","t":"Savoir quand évoquer le diagnostic de déficit immunitaire chez l’enfant et l’adulte","q":"Quel type d'infections oriente vers un déficit de l'immunité humorale (lymphocytes B) et quels bilans sont utiles ?","a":"<p>Des <strong>infections à bactéries encapsulées</strong> (notamment <strong>pneumocoque</strong>, <strong>Haemophilus influenzae b</strong>, <strong>méningocoque</strong>) orientent vers un déficit de l'immunité humorale.</p><p>Les bilans utiles sont :</p><ul><li>Le <strong>dosage pondéral des immunoglobulines (Ig)</strong>.</li><li>Les <strong>sérologies post-vaccinales et post-infectieuses</strong>.</li><li>Le dosage des <strong>sous-classes d'IgG</strong>.</li></ul>"},{"i":"ffa6577dbdeb","n":189,"o":"189-3","u":"Diagnostic positif","t":"Savoir quand évoquer le diagnostic de déficit immunitaire chez l’enfant et l’adulte","q":"Quels sont les signes cliniques orientant vers un déficit immunitaire chez l'adulte, en dehors des infections ORL et pulmonaires ?","a":"<p>Chez l'adulte, on doit évoquer un déficit immunitaire devant :</p><ul><li>Des <strong>pneumopathies ≥ 2 par an</strong>.</li><li>Des <strong>infections bactériennes invasives à germe encapsulé</strong>.</li><li>Une <strong>mycose cutanéo-muqueuse persistante</strong>.</li><li>Une <strong>diarrhée chronique avec amaigrissement</strong>.</li><li>Des <strong>maladies auto-immunes</strong> ou <strong>granulomateuses</strong>.</li><li>Des épisodes de <strong>fièvre inexpliquée</strong>.</li><li>Un <strong>antécédent familial de déficit immunitaire</strong>.</li></ul>"},{"i":"3464e9892559","n":189,"o":"189-5","u":"Diagnostic positif","t":"Connaître les complications des traitements immunosuppresseurs","q":"Quel est le risque infectieux associé à la corticothérapie ?","a":"<p>La corticothérapie, par altération dose-dépendante de l'immunité innée, expose aux <strong>infections à pyogènes</strong> et aux <strong>infections opportunistes</strong>.</p>"},{"i":"8196c129458f","n":189,"o":"189-5","u":"Diagnostic positif","t":"Connaître les complications des traitements immunosuppresseurs","q":"Quelle est la principale complication des traitements immunosuppresseurs ?","a":"<p>La principale complication des traitements immunosuppresseurs est de type <strong>infectieuse</strong>, car ils induisent un déficit immunitaire secondaire.</p>"},{"i":"e6e966c95cca","n":189,"o":"189-5","u":"Diagnostic positif","t":"Connaître les complications des traitements immunosuppresseurs","q":"Dans quel contexte et avec quelle molécule doit-on réaliser une prophylaxie contre l'anguillulose maligne ?","a":"<p>Une prophylaxie contre l'anguillulose maligne doit être réalisée avec de l'<strong>Ivermectine</strong> chez les patients sous corticoïdes ayant séjourné en pays tropical, même si le séjour est ancien.</p>"},{"i":"fe252447cce6","n":189,"o":"189-5","u":"Diagnostic positif","t":"Connaître les complications des traitements immunosuppresseurs","q":"Quelle est la prophylaxie anti-infectieuse recommandée chez un patient greffé ou sous corticothérapie prolongée pour prévenir la toxoplasmose ou la pneumocystose ?","a":"<p>Chez un patient greffé ou sous corticothérapie prolongée, la prophylaxie pour prévenir la toxoplasmose ou la pneumocystose est le <strong>Cotrimoxazole</strong>.</p>"}]};